declare module '*.png' {
  const src: string;
  export default src;
}

declare module '*.webp' {
  const src: string;
  export default src;
}

declare module '*.jpg' {
  const src: string;
  export default src;
}

declare module '*.jpeg' {
  const src: string;
  export default src;
}

declare module '*.gif' {
  const src: string;
  export default src;
}

// generated by the livekit styles build, which the submodule setup skips
declare module '@livekit/components-styles/dist/*' {
  export type UnprefixedClassNames = string;
}
